fn fs_main(@builtin(position) position: vec4f) -> @location(0) vec4f {
  var v = ((position.xy - uni.offset) / uni.scale + 0.5) * uni.frequency;
  var sum = vec4f(0.0);
  var ratio = 1.0;
  for (var octave = 0; octave < 2; octave++) {
    let f0 = floor(v);
    let f = v - f0;
    let s = f * f * (3.0 - 2.0 * f);
    let i = selector(f0.x);
    let j = selector(f0.x + 1.0);
    let y = i32(f0.y);
